function floodFill(image, sr, sc, color) {
  const original = image[sr][sc];
  if (original === color) return image;        // already that colour: nothing to do (and no endless loop)
  const rows = image.length, cols = image[0].length;
  const paint = (r, c) => {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return;   // off the image
    if (image[r][c] !== original) return;                    // another colour: the region ends here
    image[r][c] = color;                                     // paint it, which also marks it visited
    paint(r - 1, c);                                         // up
    paint(r + 1, c);                                         // down
    paint(r, c - 1);                                         // left
    paint(r, c + 1);                                         // right
  };
  paint(sr, sc);
  return image;
}

