const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];   // up, down, left, right

function floodFill(image, sr, sc, color) {
  const original = image[sr][sc];
  if (original === color) return image;            // already that colour: nothing to do
  const rows = image.length, cols = image[0].length;
  const queue = [[sr, sc]];
  image[sr][sc] = color;                           // paint on the way IN: painted means visited
  let head = 0;
  while (head < queue.length) {
    const [r, c] = queue[head++];
    for (const [dr, dc] of DIRS) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] === original) {
        image[nr][nc] = color;                     // a matching neighbour joins the region
        queue.push([nr, nc]);
      }
    }
  }
  return image;
}

static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};   // up, down, left, right

int[][] floodFill(int[][] image, int sr, int sc, int color) {
    int original = image[sr][sc];
    if (original == color) return image;          // already that colour: nothing to do
    int rows = image.length, cols = image[0].length;
    ArrayDeque<int[]> queue = new ArrayDeque<>();
    queue.add(new int[]{sr, sc});
    image[sr][sc] = color;                        // paint on the way IN: painted means visited
    while (!queue.isEmpty()) {
        int[] cell = queue.poll();
        for (int[] d : DIRS) {
            int nr = cell[0] + d[0], nc = cell[1] + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] == original) {
                image[nr][nc] = color;            // a matching neighbour joins the region
                queue.add(new int[]{nr, nc});
            }
        }
    }
    return image;
}

const int DIRS[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};       // up, down, left, right

vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
    int original = image[sr][sc];
    if (original == color) return image;          // already that colour: nothing to do
    int rows = image.size(), cols = image[0].size();
    queue<pair<int, int>> q;
    q.push({sr, sc});
    image[sr][sc] = color;                        // paint on the way IN: painted means visited
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto& d : DIRS) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] == original) {
                image[nr][nc] = color;            // a matching neighbour joins the region
                q.push({nr, nc});
            }
        }
    }
    return image;
}
